let realFileRecords=[],realJob=null,realPoll=null,workbenchStatus='',workbenchHealth=null,workbenchBusy=false;
const localBase=['127.0.0.1','localhost'].includes(location.hostname)?location.origin+'/api/tram':null;
try{const files=JSON.parse(localStorage.getItem('tram-upload-records-v1'));if(Array.isArray(files))realFileRecords=files.filter(f=>f&&typeof f.id==='string'&&typeof f.projectId==='string'&&typeof f.name==='string')}catch{}
const benchButton=document.createElement('button');benchButton.textContent='✦';benchButton.title='AI thật · Tài liệu & ý tưởng';benchButton.setAttribute('aria-label','AI thật · Tài liệu & ý tưởng');benchButton.onclick=()=>openPanel('workbench');$('.rail').insertBefore(benchButton,$('.rail').children[1]);
async function localCall(route,options={}){if(window.tramFlush)await window.tramFlush();if(!localBase)throw Error('Chức năng Codex cục bộ cần mở http://127.0.0.1:4318 trên máy đang chạy Trạm.');const response=await fetch(localBase+route,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers}});let body;try{body=await response.json()}catch{throw Error('Ứng dụng cục bộ chưa chạy. Mở bằng local-app.mjs.')};if(!response.ok)throw Error(body.error||'Không xử lý được yêu cầu.');return body}
function saveFileRecords(){try{localStorage.setItem('tram-upload-records-v1',JSON.stringify(realFileRecords))}catch{}}
panelExtensions.workbench=function(){const attached=realFileRecords.filter(f=>f.projectId===project().id);panel('AI thật · Ý tưởng & tài liệu',`<p class="notice">Codex chạy trên máy này, dùng đăng nhập ChatGPT sẵn có. Các tác vụ dùng hạn mức tài khoản. Kết quả có thể là tài liệu hoặc mã nguồn trong workspace riêng.</p><button id="checkLocal" class="full">Kiểm tra Codex cục bộ</button><p class="muted">${escapeHTML(workbenchHealth?workbenchHealth.ready?'Codex đã đăng nhập · Có thể nhận việc thật':'Codex chưa đăng nhập':workbenchStatus||'Chưa kiểm tra kết nối')}</p>${!localBase?'<p class="step-gate">Mở ứng dụng tại http://127.0.0.1:4318 để dùng agent cục bộ. Website riêng tư hiện chỉ cung cấp giao diện; không thể đọc phiên đăng nhập Codex của máy bạn từ xa.</p>':''}<h3 class="section-label">TÀI LIỆU CHO DỰ ÁN NÀY</h3><label class="upload-box">＋ Thêm tài liệu<input id="attachments" type="file" multiple accept=".txt,.md,.csv,.json,.html,.pdf,.docx" ${workbenchBusy?'disabled':''}></label><p class="muted">Tối đa 8 file, 6 MB/file. Hỗ trợ văn bản, DOCX và PDF có lớp chữ. PDF scan cần OCR. Tài liệu được đọc trên máy; văn bản trích xuất chỉ gửi cho Codex khi bạn bấm chạy.</p>${attached.map(f=>`<div class="task-row"><div><b>${escapeHTML(f.name)}</b><small>${f.characters||0} ký tự · ${f.truncated?'Đã rút gọn':'Đã đọc văn bản'}</small></div><button data-remove-file="${escapeHTML(f.id)}" title="Bỏ đính kèm" aria-label="Bỏ đính kèm ${escapeHTML(f.name)}">×</button></div>`).join('')}<form id="realIdeaForm"><label>Ý tưởng hoặc yêu cầu<textarea name="task" id="realTaskInput" required maxlength="20000" placeholder="Mô tả vấn đề, người dùng và kết quả bạn cần...">${escapeHTML(run()?.idea||'')}</textarea></label><label>Tác vụ<select name="type"><option value="suggest">Đề xuất 3 ý tưởng từ tài liệu</option><option value="plan">Lập kế hoạch chi tiết theo agent</option><option value="build">Tạo sản phẩm web MVP & kiểm tra</option><option value="role">Giao việc riêng cho một agent</option></select></label><label>Vai trò phụ trách<select name="roleId">${staff.map(a=>`<option value="${a.id}">${a.id} · ${a.role}</option>`).join('')}</select></label><p class="muted">Chế độ tạo sản phẩm cho phép Codex ghi file và chạy kiểm tra trong workspace riêng. Không tự xuất bản. Tài liệu và yêu cầu sẽ được truyền tới dịch vụ Codex của tài khoản đang đăng nhập.</p><button class="primary full" ${workbenchBusy||realJob&&['queued','running'].includes(realJob.state)?'disabled':''}>${workbenchBusy?'Đang đọc tài liệu…':'Gửi việc cho Codex thật →'}</button></form><p class="muted" role="status">${escapeHTML(workbenchStatus)}</p>${realJob?`<article class="card"><span class="state-badge">${escapeHTML({queued:'Đã nhận việc',running:'Đang chạy Codex thật',completed:'Đã nhận kết quả',failed:'Chưa hoàn tất'}[realJob.state]||realJob.state)}</span><p>${escapeHTML(realJob.error||realJob.output||'Agent đang xử lý. Không cần bấm gửi lại.')}</p>${realJob.output?'<button id="downloadReal">Tải kết quả .md</button>':''}${(realJob.artifacts||[]).map(a=>`<p><a href="${localBase?location.origin:''}/products/${encodeURIComponent(realJob.id)}/${a.name.split('/').map(encodeURIComponent).join('/')}" target="_blank" rel="noopener">${escapeHTML(a.name)}</a> <small>${a.size} bytes</small></p>`).join('')}${realJob.state==='completed'&&!realJob.artifacts?.some(a=>a.name==='index.html')?'<p class="muted">Lượt này chưa có index.html để mở sản phẩm web.</p>':''}</article>`:''}<h3 class="section-label">KHUNG KẾ HOẠCH AGENT</h3><p class="muted">Mỗi Phi Phi có mục tiêu, đầu vào, đầu ra, quy trình, tiêu chí nghiệm thu và nội dung cấu hình vai trò.</p><a class="download-plan" href="agent-plans.json" download="tram-agent-plans.json">Tải khung 12 agent (.json)</a><div id="planCards"></div>`);
$('#checkLocal').onclick=async()=>{try{workbenchHealth=await localCall('/health');workbenchStatus=workbenchHealth.ready?'Kết nối Codex sẵn sàng.':'Cần đăng nhập Codex trên máy.';}catch(e){workbenchStatus=e.message}if(drawerView==='workbench')renderPanel('workbench')};
$('#attachments').onchange=async e=>{const chosen=[...e.target.files];if(attached.length+chosen.length>8)return toast('Tối đa 8 tài liệu cho mỗi dự án.');const projectId=project().id;workbenchBusy=true;workbenchStatus='Đang trích xuất văn bản tài liệu…';try{for(const file of chosen){if(file.size>6000000)throw Error(file.name+' vượt 6 MB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const record=await localCall('/files',{method:'POST',body:JSON.stringify({name:file.name,base64,projectId})});realFileRecords.push({...record,projectId});saveFileRecords()}workbenchStatus='Đã đọc tài liệu. Bạn có thể giao việc cho Codex.'}catch(error){workbenchStatus=error.message}finally{workbenchBusy=false;if(drawerView==='workbench')renderPanel('workbench')}};
$('#realIdeaForm').onsubmit=async e=>{e.preventDefault();if(workbenchBusy||realJob&&['queued','running'].includes(realJob.state))return;const values=Object.fromEntries(new FormData(e.target));workbenchStatus='Đang gửi tác vụ tới Codex…';try{realJob=await localCall('/jobs',{method:'POST',body:JSON.stringify({...values,projectId:project().id,fileIds:realFileRecords.filter(f=>f.projectId===project().id).map(f=>f.id)})});workbenchStatus='Đã nhận việc thật. Đang theo dõi kết quả…';pollRealJob();}catch(error){workbenchStatus=error.message}if(drawerView==='workbench')renderPanel('workbench')};
$$('[data-remove-file]').forEach(b=>b.onclick=()=>{realFileRecords=realFileRecords.filter(f=>f.id!==b.dataset.removeFile);saveFileRecords();renderPanel('workbench')});if($('#downloadReal'))$('#downloadReal').onclick=()=>download('tram-ket-qua-codex.md',realJob.output,'text/markdown;charset=utf-8');
fetch('agent-plans.json').then(r=>r.json()).then(plans=>{if(drawerView!=='workbench'||!$('#planCards'))return;$('#planCards').innerHTML=plans.agents.map(a=>`<details class="card"><summary>${a.id} · ${escapeHTML(a.role)}</summary><p>${escapeHTML(a.mission)}</p><p class="muted"><b>Đầu vào</b><br>${escapeHTML(a.inputs.join('\n'))}</p><p class="muted"><b>Đầu ra</b><br>${escapeHTML(a.deliverables.join('\n'))}</p><p class="body-copy">${escapeHTML(a.steps.map((s,i)=>(i+1)+'. '+s).join('\n'))}</p><p class="body-copy"><b>Nội dung cấu hình vai trò</b>\n${escapeHTML(a.systemPrompt)}</p></details>`).join('')}).catch(()=>{});
};
async function pollRealJob(){clearTimeout(realPoll);if(!realJob||!['queued','running'].includes(realJob.state))return;try{realJob=await localCall('/jobs/'+encodeURIComponent(realJob.id));if(['completed','failed'].includes(realJob.state))workbenchStatus=realJob.state==='completed'?'Đã có đầu ra thật. Kiểm tra tài liệu, file và bằng chứng trước khi sử dụng.':realJob.error;else workbenchStatus='Codex đang làm việc thật. Bạn có thể xem các mục khác trong Trạm.';if(drawerView==='workbench')renderPanel('workbench');if(['queued','running'].includes(realJob.state))realPoll=setTimeout(pollRealJob,2500)}catch(e){workbenchStatus=e.message+' Mở lại bảng để kiểm tra, không gửi lại ngay.';if(drawerView==='workbench')renderPanel('workbench')}}

